{
  "story": "Client wants a TCP connection with listening Server. Follow SYN, SYN-ACK, and ACK across Wire using Previous and Next. Sequence numbers count positions, not elapsed time; SYN consumes a position even without payload. Compare both endpoint states before and after ACK reaches Server.",
  "aha": {
    "stateId": "established",
    "observation": "Server becomes established only after ACK confirms receipt of its SYN; sending SYN-ACK alone leaves Server waiting."
  },
  "layout": {
    "preset": "protocol",
    "width": 640
  },
  "parts": [
    {
      "id": "handshake-rail",
      "kind": "step-rail",
      "presentation": "Use the approved card shell and canonical protocol arrangement. Place explanation and instructions above the experiment. Keep progress and trace on this rail. Each index represents a discrete state, never elapsed time.",
      "bind": {
        "active": "state.id",
        "items": "variant.states"
      }
    },
    {
      "id": "endpoints-and-wire",
      "kind": "fixed-picture",
      "presentation": "Keep Client left, Wire centered, and Server right in every state. Links show connectivity, not transmission direction. Highlight only bound active regions. Wire evidence identifies the segment, direction, and delivery condition. Keep all labels readable at native card width.",
      "bind": {
        "active": "state.active",
        "links": "variant.links",
        "regions": "variant.regions"
      }
    },
    {
      "id": "active-endpoint-callout",
      "kind": "active-callout",
      "presentation": "Anchor the callout to its named target without covering labels. Identify the active mechanism here; reserve numeric values for readouts. Reference capture must show established. That state persists until the learner acts.",
      "bind": {
        "reason": "state.why",
        "target": "state.calloutRegion",
        "text": "state.sentence"
      }
    },
    {
      "id": "handshake-evidence",
      "kind": "value-readout",
      "presentation": "Place aligned readouts below the picture, with Status last. Preserve endpoint rows across states. Assume no loss, reordering, retransmission, simultaneous open, or sequence wrap; payload is absent. Initial ISNs are fixed inputs declared in Ready. Sequence fields use exact unsigned sequence positions; payload terms use bytes, with no rounding. ACK names the next expected peer sequence position. Compute ACK as peer ISN plus SYN cost plus payload length. Count transmitted TCP segments cumulatively, excluding lower-layer traffic. Materialized readouts use these same inputs and states.",
      "bind": {
        "values": "state.readouts"
      }
    }
  ],
  "controls": [
    {
      "id": "handshake-state",
      "kind": "index",
      "presentation": "Detailed parameter-control budget: zero, excluding navigation and Reset. Default index is zero; bounds are zero through four, with unit increments. Render Previous and Next, retaining their names when disabled at boundaries. Each activation selects the adjacent state and updates all evidence. All states persist without timers. Provide accessible names, visible focus, and keyboard operation.",
      "items": "variant.states",
      "label": "Handshake state"
    },
    {
      "id": "reset",
      "kind": "reset",
      "presentation": "Restore Ready and the fixed input defaults. Use the accessible name Reset, visible focus, and keyboard activation.",
      "label": "Reset"
    }
  ],
  "data": {
    "variants": [
      {
        "label": "TCP handshake",
        "regions": [
          {
            "id": "client",
            "label": "Client",
            "actors": [
              "Active opener"
            ]
          },
          {
            "id": "wire",
            "label": "Wire",
            "actors": [
              "TCP segment"
            ]
          },
          {
            "id": "server",
            "label": "Server",
            "actors": [
              "Passive listener"
            ]
          }
        ],
        "links": [
          {
            "from": "client",
            "to": "wire",
            "label": "TCP connection path"
          },
          {
            "from": "wire",
            "to": "server",
            "label": "TCP connection path"
          }
        ],
        "states": [
          {
            "id": "ready",
            "label": "Ready",
            "short": "Listening",
            "sentence": "Server is listening; Client has not sent SYN.",
            "why": "Each endpoint has its own initial sequence number, abbreviated ISN; neither endpoint has received the other's SYN.",
            "active": [
              "server"
            ],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "CLOSED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "LISTEN"
              },
              {
                "id": "wire-evidence",
                "label": "Wire evidence",
                "value": "Idle"
              },
              {
                "id": "client-isn",
                "label": "Fixed Client ISN",
                "value": "1000"
              },
              {
                "id": "server-isn",
                "label": "Fixed Server ISN",
                "value": "5000"
              },
              {
                "id": "segments-sent",
                "label": "Segments sent",
                "value": "0"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "No handshake evidence has crossed Wire."
              }
            ]
          },
          {
            "id": "syn-in-flight",
            "label": "Client sends SYN",
            "short": "SYN",
            "sentence": "SYN crosses Wire from Client to Server.",
            "why": "Client advertises its starting sequence number; SYN consumes one sequence position despite carrying no application payload.",
            "active": [
              "client",
              "wire"
            ],
            "calloutRegion": "wire",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "SYN-SENT"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "LISTEN"
              },
              {
                "id": "wire-evidence",
                "label": "Wire evidence",
                "value": "SYN · Client → Server · in transit"
              },
              {
                "id": "segment-seq",
                "label": "Segment SEQ",
                "value": "1000"
              },
              {
                "id": "segment-ack",
                "label": "Segment ACK",
                "value": "Not valid; ACK flag is off."
              },
              {
                "id": "segments-sent",
                "label": "Segments sent",
                "value": "1"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Server remains LISTEN until SYN arrives."
              }
            ]
          },
          {
            "id": "syn-ack-in-flight",
            "label": "Server replies SYN-ACK",
            "short": "SYN-ACK",
            "sentence": "Server receives SYN and replies with SYN-ACK.",
            "why": "SYN-ACK acknowledges Client's SYN and advertises Server's starting sequence number; Server still needs acknowledgment of its own SYN.",
            "active": [
              "server",
              "wire"
            ],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "SYN-SENT"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "wire-evidence",
                "label": "Wire evidence",
                "value": "SYN-ACK · Server → Client · in transit"
              },
              {
                "id": "segment-seq",
                "label": "Segment SEQ",
                "value": "5000"
              },
              {
                "id": "segment-ack",
                "label": "Segment ACK: ISN + SYN + payload",
                "value": "1000 + 1 + 0 = 1001"
              },
              {
                "id": "segments-sent",
                "label": "Segments sent",
                "value": "2"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Server acknowledges Client's SYN but cannot yet know its own SYN arrived."
              }
            ]
          },
          {
            "id": "ack-in-flight",
            "label": "Client sends ACK",
            "short": "ACK sent",
            "sentence": "Client accepts SYN-ACK and sends ACK; Server still waits.",
            "why": "Client has received Server's SYN and acknowledgment, so Client becomes established; its returning ACK has not yet reached Server.",
            "active": [
              "client",
              "wire"
            ],
            "calloutRegion": "client",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "SYN-RECEIVED"
              },
              {
                "id": "wire-evidence",
                "label": "Wire evidence",
                "value": "ACK · Client → Server · in transit"
              },
              {
                "id": "segment-seq",
                "label": "Segment SEQ",
                "value": "1001"
              },
              {
                "id": "segment-ack",
                "label": "Segment ACK: ISN + SYN + payload",
                "value": "5000 + 1 + 0 = 5001"
              },
              {
                "id": "segments-sent",
                "label": "Segments sent",
                "value": "3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "The endpoint states differ while ACK is in transit."
              }
            ]
          },
          {
            "id": "established",
            "label": "Server accepts ACK",
            "short": "Both established",
            "sentence": "Server accepts ACK; both endpoint states now show ESTABLISHED.",
            "why": "ACK matches Server's next sequence position, confirming Client received Server's SYN; a pure ACK consumes no sequence positions.",
            "active": [
              "client",
              "server"
            ],
            "calloutRegion": "server",
            "readouts": [
              {
                "id": "client-state",
                "label": "Client state",
                "value": "ESTABLISHED"
              },
              {
                "id": "server-state",
                "label": "Server state",
                "value": "ESTABLISHED"
              },
              {
                "id": "wire-evidence",
                "label": "Wire evidence",
                "value": "ACK · Client → Server · received by Server"
              },
              {
                "id": "segment-seq",
                "label": "Received segment SEQ",
                "value": "1001"
              },
              {
                "id": "segment-ack",
                "label": "Received ACK: ISN + SYN + payload",
                "value": "5000 + 1 + 0 = 5001"
              },
              {
                "id": "segments-sent",
                "label": "Segments sent",
                "value": "3"
              },
              {
                "id": "status",
                "label": "Status",
                "value": "Both SYNs are acknowledged; Server now joins Client in ESTABLISHED."
              }
            ]
          }
        ]
      }
    ]
  }
}
